        INSERT INTO [dbo].[Category] ([CategoryId], [Name])
        SELECT s.Id, s.Name FROM @Categories s
        WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Category] d WHERE d.[Name] = s.Name);

        INSERT INTO [dbo].[Area] ([AreaId], [Name])
        SELECT s.Id, s.Name FROM @Areas s
        WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Area] d WHERE d.[Name] = s.Name);

        INSERT INTO [dbo].[TypeFood] ([TypeFoodId], [Name])
        SELECT s.Id, s.Name FROM @Types s
        WHERE NOT EXISTS (SELECT 1 FROM [dbo].[TypeFood] d WHERE d.[Name] = s.Name);

        INSERT INTO [dbo].[Sizes] ([SizeId], [Name])
        SELECT s.Id, s.Name FROM @Units s
        WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Sizes] d WHERE d.[Name] = s.Name);

        DECLARE @MainCategory varchar(36) = (
            SELECT MIN([CategoryId]) FROM [dbo].[Category] WHERE [Name] = N'Nhà hàng'
        );

        INSERT INTO [dbo].[Location] ([LocationId], [Name], [Address], [Description], [ImageUrl],
                                      [Latitude], [Longitude], [CategoryId], [AreaId], [CreateAt])
        SELECT s.Id, s.Name, s.Address, s.Description, NULLIF(s.ImageUrl, N''),
               s.Latitude, s.Longitude, @MainCategory, a.Id, SYSUTCDATETIME()
        FROM @Restaurants s
        CROSS APPLY (SELECT MIN(d.[AreaId]) AS Id FROM [dbo].[Area] d WHERE d.[Name] = s.AreaName) a
        WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Location] d WHERE d.[LocationId] = s.Id);

        INSERT INTO [dbo].[LocationCategory] ([LocationId], [CategoryId])
        SELECT s.LocationId, c.Id
        FROM @RestaurantCategories s
        CROSS APPLY (SELECT MIN(d.[CategoryId]) AS Id FROM [dbo].[Category] d WHERE d.[Name] = s.CategoryName) c
        WHERE NOT EXISTS (
            SELECT 1 FROM [dbo].[LocationCategory] d WHERE d.[LocationId] = s.LocationId AND d.[CategoryId] = c.Id
        );

        DECLARE @Plan TABLE (
            FoodId varchar(36) PRIMARY KEY, LocationId varchar(36), Name nvarchar(max), Description nvarchar(max),
            ImageUrl nvarchar(max), TypeFoodId varchar(36), SizeId varchar(36), Price decimal(18,2)
        );

        INSERT INTO @Plan (FoodId, LocationId, Name, Description, ImageUrl, TypeFoodId, SizeId, Price)
        SELECT 'fm-menu-' + LOWER(LEFT(CONVERT(varchar(64),
                   HASHBYTES('SHA2_256', r.Id + '|' + i.MenuKey + '|' + i.ItemKey), 2), 28)),
               r.Id, i.Name, i.Description, i.ImageUrl, t.Id, z.Id, i.Price
        FROM @Restaurants r
        JOIN @Items i ON i.MenuKey = r.MenuKey
        CROSS APPLY (SELECT MIN(d.[TypeFoodId]) AS Id FROM [dbo].[TypeFood] d WHERE d.[Name] = i.TypeName) t
        CROSS APPLY (SELECT MIN(d.[SizeId]) AS Id FROM [dbo].[Sizes] d WHERE d.[Name] = i.UnitName) z
        WHERE NOT EXISTS (
            SELECT 1 FROM [dbo].[Foods] f
            WHERE f.[LocationId] = r.Id AND f.[FoodId] NOT LIKE 'fm-menu-%'
        );

        DECLARE @InsertedFoods TABLE (FoodId varchar(36) PRIMARY KEY);

        INSERT INTO [dbo].[Foods] ([FoodId], [LocationId], [Name], [Description], [ImageUrl], [TypeFoodId], [CreateAt])
        OUTPUT inserted.[FoodId] INTO @InsertedFoods (FoodId)
        SELECT p.FoodId, p.LocationId, p.Name, p.Description, p.ImageUrl, p.TypeFoodId, SYSUTCDATETIME()
        FROM @Plan p
        WHERE NOT EXISTS (SELECT 1 FROM [dbo].[Foods] d WHERE d.[FoodId] = p.FoodId);

        INSERT INTO [dbo].[FoodSize] ([FoodId], [SizeId], [Price])
        SELECT p.FoodId, p.SizeId, p.Price FROM @Plan p JOIN @InsertedFoods n ON n.FoodId = p.FoodId;
        """;
    }
